bool saveFileAtomic(const char* filepath, const char* content) {
  char tempPath[64];
  snprintf(tempPath, sizeof(tempPath), "%s.tmp", filepath);
  File f = LittleFS.open(tempPath, FILE_WRITE);
  if (!f) return false;
  size_t bytesWritten = f.print(content);
  f.close();
  if (bytesWritten == 0) { LittleFS.remove(tempPath); return false; }
  LittleFS.remove(filepath);
  return LittleFS.rename(tempPath, filepath);
}

void enforceStorageRetention(const char* filepath) {
  File f = LittleFS.open(filepath, FILE_READ);
  if (f && f.size() > MAX_FILE_SIZE) {
    f.close();
    char backupPath[64];
    snprintf(backupPath, sizeof(backupPath), "%s.bak", filepath);
    LittleFS.remove(backupPath);
    LittleFS.rename(filepath, backupPath);
  } else if (f) {
    f.close();
  }
}

