void setUIOverlay(UIOverlay newOverlay, uint32_t durationMs = 0) {
  // Enforce Priority logic
  if (newOverlay != OVERLAY_NONE && currentOverlay > newOverlay) {
    return; // Don't overwrite a higher priority alert with a lower one
  }
  currentOverlay = newOverlay;
  if (durationMs > 0) overlayClearMs = millis() + durationMs;
  else overlayClearMs = 0;
}

void processSyncQueue() {
  if (WiFi.status() != WL_CONNECTED || coreState != CORE_IDLE) return;
  File q = LittleFS.open("/sync_queue.jsonl", FILE_READ);
  if (!q || q.size() == 0) { if (q) q.close(); return; }

  setUIOverlay(OVERLAY_SYNCING); // Smart Notification Hook
  bool allRecordsAcknowledged = true;
  char lineBuffer[256]; size_t lineLen = 0;

  while (q.available()) {
    char c = q.read();
    if (c == '\n' || c == '\r') {
      if (lineLen > 0) {
        lineBuffer[lineLen] = '\0';
        if (!api_uploadSessionRecord(lineBuffer)) allRecordsAcknowledged = false;
        lineLen = 0;
      }
    } else if (lineLen < sizeof(lineBuffer) - 1) { lineBuffer[lineLen++] = c; }
  }
  q.close();
  if (allRecordsAcknowledged) { LittleFS.remove("/sync_queue.jsonl"); }
  if (currentOverlay == OVERLAY_SYNCING) setUIOverlay(OVERLAY_NONE); 
}

