  digitalWrite(RGB_R_PIN, r); digitalWrite(RGB_G_PIN, g); digitalWrite(RGB_B_PIN, b);
}

void updateSystemLED() {
  if (currentOverlay == OVERLAY_ALERT)       setRGB(1, 0, 0); 
  else if (currentOverlay == OVERLAY_DENIED) setRGB(1, 0, 0);
  else if (currentOverlay == OVERLAY_SYNCING)setRGB(1, 1, 0); 
  else if (currentOverlay == OVERLAY_AI)     setRGB(0, 1, 1); 
  else if (coreState == CORE_STUDYING)       setRGB(0, 1, 0); 
  else if (coreState == CORE_BREAK)          setRGB(1, 0, 1); 
  else                                       setRGB(0, 0, 1); 
}

// ---> ADDED: Touch / Interaction Abstraction
void handleUserInteraction() {
  lastUserInteractionMs = millis();
  if (currentUIMode == UI_ROCKET_FACE || currentUIMode == UI_STARTUP) {
    currentUIMode = UI_DASHBOARD;
    // Tương tác đánh thức màn hình Dashboard
  }
}

void handleSmartAlerts() {
  // Clear temporary overlays like Denied Stop
  if (overlayClearMs > 0 && millis() > overlayClearMs) {
    if (currentOverlay != OVERLAY_ALERT) { // Don't auto-clear persistent alerts
      currentOverlay = OVERLAY_NONE;
      overlayClearMs = 0;
      updateSystemLED();
    }
  }

  // Manage persistent Proximity Alert
  if (integ.proximityWarning) {
    if (currentOverlay != OVERLAY_ALERT) {
      setUIOverlay(OVERLAY_ALERT);
      buzzer.warning();
      updateSystemLED();
    }
  } else {
    if (currentOverlay == OVERLAY_ALERT) {
      setUIOverlay(OVERLAY_NONE); // UI automatically restores to Face/Dashboard!
      updateSystemLED();
    }
  }
}

// ---> ADDED: 10-Minute Idle Return
void handleUIStateLogic() {
  uint32_t now = millis();

  // Transition out of Startup Greeting after delay
  if (currentUIMode == UI_STARTUP && (now - startupTimerMs > STARTUP_DUR_MS)) {
    currentUIMode = UI_ROCKET_FACE;
    lastUserInteractionMs = now; // Reset idle timer
  }

  // Transition from Dashboard to AI Face if idle for 10 minutes
  if (currentUIMode == UI_DASHBOARD && (now - lastUserInteractionMs > IDLE_TIMEOUT_MS)) {
    // Only return to Face if we aren't actively running a pomodoro (optional UX tweak, but following spec)
    currentUIMode = UI_ROCKET_FACE;
  }
}

