void saveSessionData(SessionStatus status, const char* stopReason) {
  bool timeValid = false;
  currentSession.endTs = getBestUnixTime(timeValid);
  currentSession.durationSec = (millis() - sessionStartMs) / 1000;
  currentSession.status = status;
  strlcpy(currentSession.stopReason, stopReason, sizeof(currentSession.stopReason));

  char buf[256];
  snprintf(buf, sizeof(buf), 
    "{\"id\":\"%s\",\"plan\":\"%s\",\"start\":%lu,\"end\":%lu,\"dur\":%lu,\"status\":%d,\"reason\":\"%s\"}", 
    currentSession.id, currentSession.planId, currentSession.startTs, currentSession.endTs, currentSession.durationSec, (int)status, stopReason);

  enforceStorageRetention("/sessions.jsonl");
  File f = LittleFS.open("/sessions.jsonl", FILE_APPEND);
  if (f) { f.println(buf); f.close(); }
  enqueueSessionSync(buf); markActiveSessionOnDisk(false);
}

void startSession(uint8_t planIndex) {
  if (coreState == CORE_STUDYING) return;
  coreState = CORE_STUDYING;
  setUIOverlay(OVERLAY_NONE);
  handleUserInteraction(); // Force wake to dashboard

  bool timeValid = false; uint32_t ts = getBestUnixTime(timeValid);
  snprintf(currentSession.id, sizeof(currentSession.id), "%s-%lu", deviceId, ts);
  strlcpy(currentSession.planId, activePlans[planIndex].id, sizeof(currentSession.planId));
  currentSession.startTs = ts; currentSession.endTs = 0;
  currentSession.plannedDurationSec = activePlans[planIndex].durationSec;
  currentSession.allowStop = activePlans[planIndex].allowStop;
  currentSession.status = STATUS_ACTIVE;

  sessionStartMs = millis(); pomodoroStartMs = millis(); pomodoroActive = true;
  markActiveSessionOnDisk(true);
  buzzer.tick(); updateSystemLED();
}

void stopSession(const char* reason) {
  if (coreState != CORE_STUDYING) return;
  bool isCompleted = (strcmp(reason, "COMPLETED") == 0);
  saveSessionData(isCompleted ? STATUS_COMPLETED : STATUS_USER_STOPPED, reason);
  pomodoroActive = false;

  if (isCompleted) {
    coreState = CORE_BREAK; breakStartMs = millis(); buzzer.success();
  } else {
    coreState = CORE_IDLE; buzzer.tick();
  }
  handleUserInteraction(); // Wake UI
  updateSystemLED();
}

void handlePomodoroAndBreak() {
  uint32_t now = millis();
  if (pomodoroActive && coreState == CORE_STUDYING) {
    if ((now - pomodoroStartMs) >= currentSession.plannedDurationSec * 1000) stopSession("COMPLETED");
  }
  if (coreState == CORE_BREAK) {
    if ((now - breakStartMs) / 1000 >= breakDurationSec) {
      coreState = CORE_IDLE; buzzer.success(); updateSystemLED();
    }
  }
}

