void readSensors() {
  sysHealth.freeHeap = ESP.getFreeHeap();
  sysHealth.wifiRssi = (WiFi.status() == WL_CONNECTED) ? WiFi.RSSI() : -100;
  env.temp = dht.readTemperature();
  env.hum = dht.readHumidity();
  env.valid = (!isnan(env.temp) && !isnan(env.hum));
  env.light = analogRead(LDR_PIN);
  env.aqRaw = analogRead(AQ_PIN);

  digitalWrite(TRIG_PIN, LOW); delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  long dur = pulseIn(ECHO_PIN, HIGH, 30000);
  if (dur > 0) {
    integ.distanceCm = dur * 0.0343f / 2.0f;
    integ.presenceDetected = (integ.distanceCm <= DIST_PRESENCE_MAX);
    integ.proximityWarning = (integ.presenceDetected && integ.distanceCm < DIST_WARNING_MIN);
  } else {
    integ.distanceCm = -1.0f; integ.presenceDetected = false; integ.proximityWarning = false;
  }
}

void handleButtons() {
  uint32_t now = millis();

  if (digitalRead(START_PIN) == LOW && (now - lastStartBtn > DEBOUNCE_MS)) {
    lastStartBtn = now;
    handleUserInteraction(); // Any button wakes the UI
    if (coreState == CORE_IDLE || coreState == CORE_BREAK) {
      startSession(selectedPlanIndex);
    }
  }

  if (digitalRead(STOP_PIN) == LOW && (now - lastStopBtn > DEBOUNCE_MS)) {
    lastStopBtn = now;
    handleUserInteraction(); // Wake UI
    if (coreState == CORE_STUDYING) {
      if (currentSession.allowStop) stopSession("USER_STOPPED");
      else {
        setUIOverlay(OVERLAY_DENIED, 2500); // 2.5s duration
        buzzer.denied();
        updateSystemLED();
      }
    }
  }
}

