}

void renderNotificationOverlay(UIOverlay overlay) {
  // Renders over whatever was on the screen, or takes it over temporarily
  if (overlay == OVERLAY_ALERT) {
    display.setTextSize(2);
    display.setCursor(10, 30); display.print("TOO CLOSE!");
    display.setTextSize(1);
  } else if (overlay == OVERLAY_DENIED) {
    display.setCursor(5, 25); display.print("STOP DENIED!");
    display.setCursor(5, 40); display.print("Controlled Task");
    display.setCursor(5, 52); display.print("In Progress...");
  } else if (overlay == OVERLAY_SYNCING) {
    display.setCursor(10, 30); display.print("Syncing Data...");
  }
}

void handleDisplay() {
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);

  // Notification Priority Architecture: Overlays temporarily replace UI
  if (currentOverlay != OVERLAY_NONE) {
    renderNotificationOverlay(currentOverlay);
  } else {
    // Normal View State Machine
    switch(currentUIMode) {
      case UI_STARTUP:     renderStartupGreeting(); break;
      case UI_ROCKET_FACE: renderRocketFace();      break;
      case UI_DASHBOARD:   renderDashboard();       break;
    }
  }
  display.display();
}

