void setup() {
  Serial.begin(115200);

  preferences.begin("rgo", false);
  sysHealth.bootCount = preferences.getUInt("boots", 0) + 1;
  preferences.putUInt("boots", sysHealth.bootCount);

  String savedId = preferences.getString("id", "");
  if (savedId == "") {
    snprintf(deviceId, sizeof(deviceId), "RG-%08X", (uint32_t)ESP.getEfuseMac());
    preferences.putString("id", String(deviceId));
  } else {
    strlcpy(deviceId, savedId.c_str(), sizeof(deviceId));
  }

  initStorage();
  Wire.begin(SDA_PIN, SCL_PIN);
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  dht.begin();

  pinMode(TRIG_PIN, OUTPUT); 
  pinMode(ECHO_PIN, INPUT);
  pinMode(START_PIN, INPUT_PULLUP); 
  pinMode(STOP_PIN, INPUT_PULLUP);
  pinMode(RGB_R_PIN, OUTPUT); 
  pinMode(RGB_G_PIN, OUTPUT); 
  pinMode(RGB_B_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  configTime(GMT_OFFSET, 0, NTP_SERVER);

  touchUI_Init();
  voiceAI_Init();

  coreState = CORE_IDLE;
  currentUIMode = UI_STARTUP;
  startupTimerMs = millis(); // Start the startup greeting timer

  updateSystemLED();
  Serial.printf("[SYSTEM] Boot completed. Device ID: %s | Boot #%u\n", deviceId, sysHealth.bootCount);
}

void loop() {
  uint32_t now = millis();
  buzzer.update();

  if (WiFi.status() != WL_CONNECTED && now - lastWifiTs > INTERVAL_WIFI) {
    WiFi.reconnect(); 
    lastWifiTs = now;
  }

  if (now - lastSensorTs > INTERVAL_SENSOR) {
    updateTimeManager();
    readSensors(); 
    sendTelemetry(); 
    lastSensorTs = now;
  }

  // Non-blocking Display Logic & State Handlers
  handleUIStateLogic();

  if (now - lastOledTs > INTERVAL_OLED) {
    handleDisplay(); 
    lastOledTs = now;
  }

  handleButtons();
  handleSmartAlerts();
  handlePomodoroAndBreak();

  touchUI_Update();
  voiceAI_Update();

  static uint32_t lastSyncAttempt = 0;
  if (now - lastSyncAttempt > 15000) {
    processSyncQueue();
    lastSyncAttempt = now;
  }
}
